import {captureCalculation} from './material-notebook.js?v=20261031-entry1';
import {esc,num,table} from './response-views.js?v=20261031-entry1';
let latest=null;
export const getAuditResult=()=>latest;
export function renderAuditView({container,run,cancelRun,download,onLocation=()=>{}}){
 latest=null;let ticket=0;
 container.innerHTML=`<div class="obs-page connections-page"><header class="obs-header"><span class="obs-eyebrow">MODEL · STATE · MEASUREMENT</span><h2>三层对称性诊断工坊</h2><p>用同一个二能级模型分别检验哈密顿量、状态与测量探针。可从任意计算工具进入，并将证据收录到材料研究记录。</p></header><section class="ct-panel"><div class="obs-formula">H = h_x σ_x + h_z σ_z</div><div class="obs-formula">ρ = (I + r n·σ)/2</div><p>态方向与探针方向均在 xz 平面，角度从 +z 向 +x 测量；瞬时态不要求是 H 的平衡态。</p><form id="audit-form"><label>操作<select id="audit-operation"><option value="z">σz 幺正变换</option><option value="time">自旋 1/2 时间反演 iσy K</option></select></label><div class="cn-audit-controls">${[['hx','hₓ',1,-2,2],['hz','h_z',0,-2,2],['stateAngle','态方向角（度）',0,-180,180],['probeAngle','探针方向角（度）',90,-180,180],['polarization','Bloch 向量长度 r',1,0,1]].map(([k,t,v,min,max])=>`<label>${t}<input id="audit-${k}" type="number" required step="any" min="${min}" max="${max}" value="${v}"></label>`).join('')}</div><button class="primary" type="submit" id="audit-run">检验三层对称性</button><button class="secondary" type="button" id="audit-cancel">取消</button></form><div id="audit-result" role="status">先运行默认例子：H 不保留 σz，而所选态保留 σz，奇探针的期望仍被强制为零。</div></section><div class="obs-links"><a href="#classroom/foundations?module=statistics">同粒子与符号步骤 →</a><a href="#classroom/structure-dynamics?module=defects">缺陷与反例 →</a><a href="#classroom/observables?module=reciprocity">响应约束 →</a><a href="#atlas/compare">参数对照 →</a><a href="#atlas/notebook">保存材料研究记录 →</a></div></div>`;
 const root=container.firstElementChild,$=s=>root.querySelector(s),current=()=>root.parentNode===container&&container.isConnected!==false;
 onLocation('计算中心 / 三层对称性诊断工坊');
 const invalidate=()=>{ticket++;latest=null;cancelRun?.();$('#audit-run').disabled=false;$('#audit-result').textContent='参数已改变，请重新检验。';};$('#audit-form').oninput=invalidate;$('#audit-cancel').onclick=invalidate;
 $('#audit-form').onsubmit=async e=>{e.preventDefault();const id=++ticket,input=Object.fromEntries(['hx','hz','stateAngle','probeAngle','polarization'].map(k=>[k,Number($('#audit-'+k).value)]));input.operation=$('#audit-operation').value;latest=null;$('#audit-run').disabled=true;$('#audit-result').textContent='正在运行 Python 诊断…';try{const r=await run('symmetry_audit',input);if(!current()||id!==ticket)return;latest={module:'audit',input,result:r};captureCalculation('symmetry_audit',input,r,{route:'compute/symmetry-audit',title:'三层对称性诊断'});$('#audit-result').innerHTML=table(['层次 / 结论','残差或结果'],[['模型 H',num(r.hamiltonian)],['状态 ρ',num(r.state)],['探针 O',num(r.probe)],['探针为奇',r.probeOdd?'是':'否'],['期望值',num(r.expectation)],['由此对称性强制为零',r.forcedZero?'是':'否']])+`<p>${esc(r.note)}</p><button id="audit-export" class="secondary">导出诊断证据 JSON</button>`;$('#audit-export').onclick=()=>download?.(JSON.stringify(latest,null,2),'symmetry-audit.json','application/json');}catch(e){if(current()&&id===ticket)$('#audit-result').textContent=e.message;}finally{if(current()&&id===ticket)$('#audit-run').disabled=false;}};
}
